query HomePageQuery {
  active: listoryChecklistSearch(where: {completed: false}, first: 5) {
    totalCount
    nodes {
      id
      ...HomePage_checklist
    }
  }
  lists: listoryListSearch(first: 1) {
    totalCount
  }
}

fragment HomePage_checklist on ListoryChecklist {
  id
  title
  items(first: 100) {
    totalCount
    nodes {
      checked
      id
    }
  }
}

query ListPageQuery(
  $term: String = ""
) {
  ...ListList_query_4hh6ED
}

fragment ListList_query_4hh6ED on RootQuery {
  listoryListSearch(first: 25, where: {term: $term}) {
    totalCount
    edges {
      node {
        id
        title
        items {
          totalCount
        }
        __typename
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

